$('#restart').onclick=()=>{openDialog('<h2>Начать другую жизнь?</h2><p class="muted">Текущая жизнь останется в архиве на этом устройстве. Историю также можно скачать.</p><button class="secondary" id="keep-history">Скачать историю</button><button class="primary" id="confirm-restart">Начать заново →</button>');$('#keep-history').onclick=download;$('#confirm-restart').onclick=()=>{ReferenceController.archive(state);state=E.fresh();F.ensure(state).simple=true;menuOpen=false;tab='story';save();$('#dialog').close();render();};};$('#help').onclick=()=>openDialog(simpleModelView());$('#main-menu').onclick=goMainMenu;$('.brand').onclick=event=>{event.preventDefault();goMainMenu();};render();


$('#theme-preview').disabled=false;$('#theme-preview').setAttribute('aria-label','Переключить тему');$('#theme-preview').title='Переключить тему';$('#theme-preview').onclick=()=>LifePreferences.toggleTheme();

function cashLabel(n){return new Intl.NumberFormat('ru-RU',{notation:Math.abs(n)>=10000?'compact':'standard',maximumFractionDigits:Math.abs(n)>=10000?1:0}).format(n)+' $';}
function financeOverview(sim){const f=sim.finance,worth=state.reference?.snapshot?.netWorth??(f.balance+(f.invested||0)-(f.debt||0)),rows=[['Доход / год',f.income],['Состояние',worth],...(f.debt>0?[['Долг',f.debt]]:[])];return `<button class="scene-finance-summary" data-stat="money" aria-label="Открыть подробности финансов">${rows.map(([name,value])=>`<span class="scene-finance-row${name==='Долг'?' finance-debt':''}"><span>${name}</span><b title="${LifeSimulation.format(value)}">${cashLabel(value)}</b></span>`).join('')}</button>`;}
function simulationStats(){const f=LifeSimulation.ensure(state).finance,worth=state.reference?.snapshot?.netWorth??(f.balance+(f.invested||0)-(f.debt||0)),money=[[f.owner==='family'?'Баланс семьи':'Баланс',f.balance],['Доход / год',f.income],['Состояние',worth],...(f.debt>0?[['Долг',f.debt]]:[])];return `<div class="top-stats scene-status-ribbon" role="group" aria-label="Показатели жизни"><div class="ribbon-needs">${['health','joy','bond'].map(key=>`<button class="ribbon-need" data-stat="${key}" aria-label="${topStatNames[key]}: ${state.stats[key]} из 100" title="${topStatNames[key]}"><span class="ribbon-need-icon">${statIcon(key)}</span><span class="ribbon-need-track" role="progressbar" aria-label="${topStatNames[key]}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${state.stats[key]}"><i style="width:${state.stats[key]}%;background:${{health:'#cf8591',joy:'#c6ad6d',bond:'#8c9ebc'}[key]}"></i><b>${state.stats[key]}</b></span></button>`).join('')}</div></div><button class="scene-knowledge" data-stat="skill" aria-label="Знания: ${Math.round(state.stats.skill)} из 100. Открыть обучение"><span>Знания</span><b>${Math.round(state.stats.skill)}<small> / 100</small></b></button><div class="scene-finance-corner" role="group" aria-label="Финансы">${money.map(([name,value],i)=>`<button data-stat="money" class="ribbon-cash${name==='Долг'?' ribbon-debt':''}" aria-label="${name}: ${LifeSimulation.format(value)}. Открыть бюджет"><span>${i===0?statIcon('money'):''}${name}</span><b title="${LifeSimulation.format(value)}">${cashLabel(value)}</b></button>`).join('')}</div>${yearFocus()}`;}

function simulationActions(section='all'){const d=LifeSimulation.ensure(state),items=LifeSimulation.actions(state,section);return `${state.reference?(state.age<6?'<p class="tiny">Два детских действия за год · без затрат</p>':'<p class="tiny">Доступность зависит от возраста, событий и бюджета.</p>'):`<p class="tiny">${Math.max(0,2-(d.actions.year===state.age?d.actions.used:0))} действия на этот год · приоритеты действуют отдельно</p>`}${items.length?`<div class="simulation-actions">${items.map(a=>`<div><button class="secondary" data-sim-action="${a.id}" ${a.disabled?'disabled':''}>${esc(a.title)}</button>${a.reason||a.cost||a.note?`<small>${esc(a.reason||[a.note,a.cost?LifeSimulation.format(a.cost):''].filter(Boolean).join(' · '))}</small>`:''}</div>`).join('')}</div>`:'<p class="event-desc">Пока решения принимают взрослые. Собственные действия появятся с шести лет.</p>'}`;}
function simulationSummary(){const d=LifeSimulation.ensure(state),f=d.finance;return `<div class="character-profile"><div class="character-profile-avatar">${FamilyAppearance.markup(state,'self')}</div><div class="character-profile-info"><h2 class="event-title">${esc(state.origin.name)}</h2><p>${flowAge(state.flow.months)}</p><p>${esc(LifeSimulation.occupation(state))} · ${esc(state.origin.currentCountry||d.home)}</p>${d.childCare?.traits?.length?`<p class="character-inclination">Склонность: ${esc([...d.childCare.traits].sort((a,b)=>b.value-a.value)[0].label.toLowerCase())}</p>`:''}<div class="simulation-summary">${state.reference?'':`<span>Силы <b>${Math.round(state.stats.energy)} / 100</b></span>`}<span>Баланс <b>${LifeSimulation.format(f.balance)}</b></span>${f.debt?`<span>Долг <b>${LifeSimulation.format(f.debt)}</b></span>`:''}${d.capsule?.result?`<span>Капсула времени <b>${esc(d.capsule.result.label)}</b></span>`:''}${d.partner?`<span>Партнёр <b>${esc(d.partner)}</b></span>`:''}${d.children.length?`<span>Дети <b>${d.children.length}</b></span>`:''}</div></div></div><h3>Ваши действия</h3><div class="simulation-groups">${Object.entries(actionGroups).map(([key,title])=>`<button class="secondary" data-sim-section="${key}">${title}</button>`).join('')}</div>${familyPanel()}${d.partner?`<div class="person-card"><div><h3>${esc(d.partner)}</h3><p>Партнёр · близость ${Math.round(state.social.partner?.closeness||0)} / 100</p></div></div>`:''}${d.children.map(c=>`<div class="person-card"><div><h3>${esc(c.name)}</h3><p>${flowAge(state.flow.months-c.born)}</p></div></div>`).join('')}${d.contacts.filter(p=>p.kind==='Друг').map(p=>`<div class="person-card"><div><h3>${esc(p.name)}</h3><p>${esc(p.kind)}</p></div></div>`).join('')}`;}
function financeView(){if(state.reference)return referenceFinanceView();const d=LifeSimulation.ensure(state),f=d.finance;return `<h2>${f.owner==='family'?'Бюджет семьи':'Ваш бюджет'}</h2><p class="stat-detail-value">${LifeSimulation.format(f.balance)}</p><p class="tiny">Условные доллары по покупательной способности (PPP). Это игровые деньги; оценки зарплат и цен — допущения модели.</p><dl class="finance-details"><div><dt>Доход за последний год</dt><dd>${LifeSimulation.format(f.income)}</dd></div><div><dt>Расходы за последний год</dt><dd>${LifeSimulation.format(f.expenses)}</dd></div><div><dt>Накопленный долг</dt><dd>${LifeSimulation.format(f.debt)}</dd></div><div><dt>Проценты за последний год</dt><dd>${LifeSimulation.format(f.interest)}</dd></div><div><dt>Инвестиции</dt><dd>${LifeSimulation.format(f.invested)}</dd></div></dl>${simulationActions('money')}<h3>Последние операции</h3>${f.ledger.slice(-5).reverse().map(e=>`<p class="tiny">${flowAge(e.month)} · ${esc(e.label)} · ${e.amount>0?'+':''}${LifeSimulation.format(e.amount)}</p>`).join('')||'<p class="tiny">Операций пока нет.</p>'}`;}
function showSimulationSection(section){state.flow.playing=false;save();openDialog(section==='money'?financeView():`<h2>${actionGroups[section]}</h2>${state.age<6&&['health','hobby','people'].includes(section)&&LifeSimulation.ensure(state).childCare?`<p class="tiny">${esc(LifeSimulation.ensure(state).childCare.label)}</p>`:''}${{health:'health',people:'bond',hobby:'joy'}[section]?`<p class="stat-detail-value">${Math.round(state.stats[{health:'health',people:'bond',hobby:'joy'}[section]])} <span>/ 100</span></p>`:''}${section==='study'?`<p class="event-desc">Знания: ${Math.round(state.stats.skill)} / 100. Подготовка влияет на поступление и работу.</p>`:''}${section==='work'?`<p class="event-desc">${esc(LifeSimulation.occupation(state))}</p>`:''}${simulationActions(section)}`);bindSimulation();}
function bindSimulation(){document.querySelectorAll('[data-reference-setting]').forEach(b=>b.onclick=()=>{if(ReferenceController.action('setting',{key:b.dataset.referenceSetting}))$('#dialog').close();});document.querySelectorAll('[data-reference-policy]').forEach(b=>b.onclick=()=>{if(ReferenceController.action('policy',{key:b.dataset.referencePolicy,value:b.dataset.value}))$('#dialog').close();});document.querySelectorAll('[data-reference-invest]').forEach(b=>b.onclick=()=>{if(ReferenceController.action('invest',{key:b.dataset.referenceInvest})){$('#dialog').close();}});$('#reference-archive')?.addEventListener('click',showArchivedLives);document.querySelectorAll('[data-sim-section]').forEach(b=>b.onclick=()=>showSimulationSection(b.dataset.simSection));document.querySelectorAll('[data-sim-action]').forEach(b=>b.onclick=()=>{const result=LifeSimulation.perform(state,b.dataset.simAction);if(!result.ok){toast(result.text);return;}if(result.pending){if($('#dialog').open)$('#dialog').close();state.flow.playing=false;tab='story';render();return;}for(const e of LifeSimulation.drain(state))F.add(state,e.type,e.text,e.scene,e.title);if($('#dialog').open)$('#dialog').close();state.flow.playing=false;if(F.pending(state)&&state.uiHints)delete state.uiHints.deferredDecision;save();tab='story';render();toast(result.text);});}

function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3500);}

function musicControl(){const prefs=LifePreferences.get(),track=LifePreferences.tracks()[prefs.musicTrack];return `<button id="cycle-music" class="player-action player-music ${prefs.music?'music-'+track.color:'music-off'}" aria-pressed="${prefs.music}" aria-label="${prefs.music?'Музыка: '+track.name+'. Следующая мелодия':'Музыка выключена. Включить первую мелодию'}" title="${prefs.music?track.name:'Музыка выключена'}"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M9 4v12.2A3.5 3.5 0 1 0 11 19V8l8-2v8.2A3.5 3.5 0 1 0 21 17V1Z"/></svg></button>`;}
function updateMusicButton(){const button=$('#cycle-music');if(!button)return;const template=document.createElement('template');template.innerHTML=musicControl();const fresh=template.content.firstElementChild;for(const attr of ['class','aria-pressed','aria-label','title'])button.setAttribute(attr,fresh.getAttribute(attr));}

function referenceFinanceView(){const snap=state.reference.snapshot,f=LifeSimulation.money(state);return `<h2>Ваш бюджет</h2><p class="stat-detail-value">${LifeSimulation.format(f.balance)}</p><p class="tiny">Доллары по покупательной способности (PPP), как в модели 1in8b.</p><dl class="finance-details"><div><dt>Годовой доход</dt><dd>${LifeSimulation.format(f.income)}</dd></div><div><dt>Общее состояние</dt><dd>${LifeSimulation.format(snap.netWorth)}</dd></div><div><dt>Долги и отрицательный баланс</dt><dd>${LifeSimulation.format(f.debt)}</dd></div></dl>${state.age>=18?`<h3>Сбережения</h3><div class="simulation-actions">${(snap.investments||[]).map(i=>`<button class="secondary" data-reference-invest="${esc(i.id)}" ${i.disabled||i.selected||!!LifeSimulation.pending(state)?'disabled':''}>${esc(i.title)}${i.selected?' ✓':''}</button>`).join('')}</div>`:''}${referencePolicies()}${simulationActions('money')}`;}
function referenceModelView(){return `<h2 class="event-title">О вашей жизни</h2><p class="event-desc">Приоритеты действуют в течение года. События, учёба, работа, семья, покупки и сбережения рассчитываются движком 1in8b 0.8.63. Доступные действия — в разделе «Персонаж» и под значками показателей.</p><p class="tiny">Страна рождения выбирается по нашим весам ООН для 237 стран и территорий. В 172 странах используются исходные профили 1in8b; ещё в 65 — данные ООН и Всемирного банка с приближениями по близкой стране.${state.origin.referenceApprox?' Для этой страны используется дополнительный профиль с приближениями.':''}</p><p class="tiny">Код 1in8b используется с разрешения автора, подтверждённого владельцем Lifeline. Внешние сервисы оригинала и его серверные функции не подключены. Старая жизнь продолжается по прежней модели; новый движок включается при новом рождении.</p><p><a href="https://1in8b.life/" target="_blank" rel="noopener">1in8b — автор оригинальной модели</a></p><button class="secondary" id="reference-archive">Сохранённые жизни</button>${birthSourceLink()}`;}
function showArchivedLives(){const lives=ReferenceController.archived();openDialog(`<h2>Сохранённые жизни</h2>${lives.map((entry,i)=>`<button class="secondary" data-restore-life="${i}">${esc(entry.state.origin.name)} · ${ageText(entry.state.age)}</button>`).join('')||'<p>Пока нет сохранённых жизней.</p>'}<p class="tiny">На устройстве хранятся последние пять жизней.</p>`);document.querySelectorAll('[data-restore-life]').forEach(b=>b.onclick=()=>{const restored=JSON.parse(JSON.stringify(lives[Number(b.dataset.restoreLife)].state));ReferenceController.archive(state);state=restored;state.flow.playing=false;tab='story';menuOpen=false;$('#dialog').close();save();render();});}

function referencePolicies(){const snap=state.reference.snapshot,raw=snap.raw,disabled=!!LifeSimulation.pending(state),groups=state.age<18?[]:[['gift','Подарки и семейные события',[['full','Полная сумма'],['some','По средствам'],['none','Без расходов']],'full'],['diet','Питание',[['usual','Обычное'],['good','Сбалансированное'],['out','Частая доставка']],'usual'],['ins','Страхование',[['base','Базовое'],['more','Расширенное']],'base'],...(snap.surname?.available?[['sur','Фамилия детей',[['f','Отца'],['m','Матери']],snap.surname.value]]:[])];return groups.map(([key,title,choices,fallback])=>`<details><summary>${title}</summary><div class="simulation-actions">${choices.map(([value,label])=>`<button class="secondary" data-reference-policy="${key}" data-value="${value}" ${disabled||(key==='sur'&&snap.surname.fixed)?'disabled':''} aria-pressed="${(raw.flags[key]||fallback)===value}">${label}${(raw.flags[key]||fallback)===value?' ✓':''}</button>`).join('')}</div></details>`).join('')+((snap.settings||[]).length?`<details><summary>Повторять автоматически</summary><div class="simulation-actions">${snap.settings.map(item=>`<button class="secondary" data-reference-setting="${esc(item.id)}" aria-pressed="${item.on}" ${disabled?'disabled':''}>${esc(item.title)}${item.on?' ✓':''}</button>`).join('')}</div></details>`:'');}

// The art editor stores appearance separately; resuming the game refreshes only the drawing.
window.addEventListener('storage',event=>{if(event.key===LifelineGameArt.storageKey(state)||event.key===FamilyAppearance.storageKey(state)){FamilyAppearance.mount(document,state);LifelineGameArt.mount(document,state,'home');}});
window.addEventListener('focus',()=>{FamilyAppearance.mount(document,state);LifelineGameArt.mount(document,state,'home');});

document.addEventListener('pointerdown',event=>{const picker=document.querySelector('.scene-priorities[open]');if(picker&&!picker.contains(event.target))picker.open=false;});
